/**
 * GIH Operations Cloud — database schema (Release 1).
 *
 * Conventions
 * - UUID primary keys generated by the database.
 * - Every firm-owned table carries `firm_id`; row-level security policies in
 *   drizzle/0001_security.sql restrict those tables to the firms set in
 *   `app.firm_ids` for the current transaction.
 * - Timestamps are `timestamptz`. Money is integer minor units + ISO currency.
 * - Soft delete (`deleted_at`) on leads and clients so audit trails stay intact.
 */
import { sql } from "drizzle-orm";
import {
  bigserial,
  boolean,
  customType,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const citext = customType<{ data: string }>({ dataType: () => "citext" });

const id = () => uuid("id").primaryKey().default(sql`gen_random_uuid()`);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();

/* ───────────────────────── Enums ───────────────────────── */

export const firmStatus = pgEnum("firm_status", ["active", "inactive"]);
export const officeKind = pgEnum("office_kind", ["gih_centre", "partner_office", "firm_office"]);
export const userStatus = pgEnum("user_status", ["invited", "active", "deactivated"]);
export const userKind = pgEnum("user_kind", ["staff", "client"]);
export const roleScope = pgEnum("role_scope", ["group", "firm", "portal"]);
export const membershipStatus = pgEnum("membership_status", ["active", "suspended"]);
export const stageCategory = pgEnum("stage_category", ["open", "won", "lost", "closed"]);
export const leadPriority = pgEnum("lead_priority", ["low", "normal", "high", "urgent"]);
export const leadSource = pgEnum("lead_source", [
  "website_form",
  "assessment_form",
  "email",
  "whatsapp",
  "referral",
  "manual",
  "integration",
  "hub_intake",
]);
export const clientStatus = pgEnum("client_status", ["active", "inactive", "archived"]);
export const activityType = pgEnum("activity_type", [
  "created",
  "updated",
  "note",
  "stage_change",
  "assignment",
  "follow_up",
  "consent",
  "duplicate_flagged",
  "converted",
  "routed",
  "proposal",
]);
export const proposalStatus = pgEnum("proposal_status", [
  "draft",
  "in_review",
  "changes_requested",
  "approved",
  "released",
  "accepted",
  "declined",
  "withdrawn",
]);
export const consentPurpose = pgEnum("consent_purpose", ["contact", "data_processing", "marketing"]);
export const intakeStatus = pgEnum("intake_status", ["new", "routed", "held", "rejected", "duplicate"]);
export const routingAction = pgEnum("routing_action", ["route", "hold", "consult"]);
export const emailStatus = pgEnum("email_status", ["sent", "not_configured", "failed"]);

/* ───────────────────── Organisation ───────────────────── */

export const organisations = pgTable("organisations", {
  id: id(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  hqCountry: text("hq_country").notNull(),
  createdAt: createdAt(),
});

export const firms = pgTable(
  "firms",
  {
    id: id(),
    orgId: uuid("org_id").notNull().references(() => organisations.id),
    slug: text("slug").notNull(),
    legalName: text("legal_name").notNull(),
    tradingName: text("trading_name").notNull(),
    refPrefix: text("ref_prefix").notNull(),
    brandColor: text("brand_color").notNull().default("#3d3a36"),
    logoUrl: text("logo_url"),
    website: text("website"),
    emailDomain: text("email_domain"),
    contactEmail: text("contact_email"),
    contactPhone: text("contact_phone"),
    jurisdictions: text("jurisdictions").array().notNull().default(sql`'{}'::text[]`),
    status: firmStatus("status").notNull().default("active"),
    shareAggregateMetrics: boolean("share_aggregate_metrics").notNull().default(true),
    allowGroupAdminAccess: boolean("allow_group_admin_access").notNull().default(false),
    requireMfaForAll: boolean("require_mfa_for_all").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("firms_slug_uq").on(t.slug), uniqueIndex("firms_ref_prefix_uq").on(t.refPrefix)],
);

export const offices = pgTable("offices", {
  id: id(),
  orgId: uuid("org_id").notNull().references(() => organisations.id),
  name: text("name").notNull(),
  kind: officeKind("kind").notNull().default("gih_centre"),
  addressLine1: text("address_line1"),
  addressLine2: text("address_line2"),
  city: text("city"),
  country: text("country").notNull(),
  timezone: text("timezone").notNull(),
  createdAt: createdAt(),
});

export const firmOffices = pgTable(
  "firm_offices",
  {
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    officeId: uuid("office_id").notNull().references(() => offices.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.firmId, t.officeId] })],
);

export const departments = pgTable(
  "departments",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("departments_firm_name_uq").on(t.firmId, t.name)],
);

/* ─────────────────── Identity & access ─────────────────── */

export const users = pgTable("users", {
  id: id(),
  orgId: uuid("org_id").notNull().references(() => organisations.id),
  email: citext("email").notNull().unique(),
  name: text("name").notNull(),
  passwordHash: text("password_hash"),
  status: userStatus("status").notNull().default("invited"),
  kind: userKind("kind").notNull().default("staff"),
  mfaSecretEnc: text("mfa_secret_enc"),
  mfaEnabledAt: timestamp("mfa_enabled_at", { withTimezone: true }),
  mfaLastTimeStep: integer("mfa_last_time_step"),
  lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
  passwordChangedAt: timestamp("password_changed_at", { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const sessions = pgTable(
  "sessions",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull().unique(),
    mfaVerified: boolean("mfa_verified").notNull().default(false),
    activeFirmId: uuid("active_firm_id").references(() => firms.id, { onDelete: "set null" }),
    ip: text("ip"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

export const mfaRecoveryCodes = pgTable(
  "mfa_recovery_codes",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    codeHash: text("code_hash").notNull(),
    usedAt: timestamp("used_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("mfa_recovery_user_idx").on(t.userId)],
);

export const authAttempts = pgTable(
  "auth_attempts",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    email: citext("email"),
    ip: text("ip"),
    kind: text("kind").notNull(), // password | mfa | reset
    succeeded: boolean("succeeded").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("auth_attempts_email_idx").on(t.email, t.createdAt), index("auth_attempts_ip_idx").on(t.ip, t.createdAt)],
);

export const passwordResets = pgTable("password_resets", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  tokenHash: text("token_hash").notNull().unique(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  usedAt: timestamp("used_at", { withTimezone: true }),
  createdAt: createdAt(),
});

export const roles = pgTable(
  "roles",
  {
    id: id(),
    orgId: uuid("org_id").notNull().references(() => organisations.id),
    key: text("key").notNull(),
    name: text("name").notNull(),
    description: text("description"),
    scope: roleScope("scope").notNull(),
    permissions: text("permissions").array().notNull().default(sql`'{}'::text[]`),
    isSystem: boolean("is_system").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("roles_org_key_uq").on(t.orgId, t.key)],
);

export const groupMemberships = pgTable(
  "group_memberships",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    roleId: uuid("role_id").notNull().references(() => roles.id),
    createdById: uuid("created_by_id").references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("group_memberships_user_uq").on(t.userId)],
);

export const firmMemberships = pgTable(
  "firm_memberships",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    roleId: uuid("role_id").notNull().references(() => roles.id),
    departmentId: uuid("department_id").references(() => departments.id, { onDelete: "set null" }),
    title: text("title"),
    status: membershipStatus("status").notNull().default("active"),
    createdById: uuid("created_by_id").references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("firm_memberships_firm_user_uq").on(t.firmId, t.userId), index("firm_memberships_user_idx").on(t.userId)],
);

export const invitations = pgTable(
  "invitations",
  {
    id: id(),
    orgId: uuid("org_id").notNull().references(() => organisations.id),
    email: citext("email").notNull(),
    name: text("name").notNull(),
    tokenHash: text("token_hash").notNull().unique(),
    firmId: uuid("firm_id").references(() => firms.id, { onDelete: "cascade" }),
    roleId: uuid("role_id").notNull().references(() => roles.id),
    invitedById: uuid("invited_by_id").notNull().references(() => users.id),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    acceptedAt: timestamp("accepted_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("invitations_email_idx").on(t.email)],
);

/* ─────────────────────── CRM ─────────────────────── */

export const firmSequences = pgTable(
  "firm_sequences",
  {
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    key: text("key").notNull(),
    value: integer("value").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.firmId, t.key] })],
);

export const pipelineStages = pgTable(
  "pipeline_stages",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    key: text("key").notNull(),
    name: text("name").notNull(),
    position: integer("position").notNull(),
    category: stageCategory("category").notNull().default("open"),
    isActive: boolean("is_active").notNull().default(true),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("pipeline_stages_firm_key_uq").on(t.firmId, t.key)],
);

export const leads = pgTable(
  "leads",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    ref: text("ref").notNull(),
    firstName: text("first_name").notNull(),
    lastName: text("last_name"),
    email: citext("email"),
    phone: text("phone"),
    nationality: text("nationality"),
    currentCountry: text("current_country"),
    destinationCountry: text("destination_country"),
    immigrationCategory: text("immigration_category"),
    enquiry: text("enquiry"),
    source: leadSource("source").notNull().default("manual"),
    sourceDetail: text("source_detail"),
    assignedToId: uuid("assigned_to_id").references(() => users.id, { onDelete: "set null" }),
    priority: leadPriority("priority").notNull().default("normal"),
    stageId: uuid("stage_id").notNull().references(() => pipelineStages.id),
    followUpAt: timestamp("follow_up_at", { withTimezone: true }),
    tags: text("tags").array().notNull().default(sql`'{}'::text[]`),
    customFields: jsonb("custom_fields").$type<Record<string, string>>().notNull().default({}),
    duplicateOfId: uuid("duplicate_of_id"),
    convertedClientId: uuid("converted_client_id"),
    convertedAt: timestamp("converted_at", { withTimezone: true }),
    intakeItemId: uuid("intake_item_id"),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("leads_firm_ref_uq").on(t.firmId, t.ref),
    index("leads_firm_stage_idx").on(t.firmId, t.stageId),
    index("leads_firm_assignee_idx").on(t.firmId, t.assignedToId),
    index("leads_firm_email_idx").on(t.firmId, t.email),
    index("leads_firm_phone_idx").on(t.firmId, t.phone),
    index("leads_firm_follow_up_idx").on(t.firmId, t.followUpAt),
    index("leads_firm_created_idx").on(t.firmId, t.createdAt),
  ],
);

export const clients = pgTable(
  "clients",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    ref: text("ref").notNull(),
    firstName: text("first_name").notNull(),
    lastName: text("last_name"),
    email: citext("email"),
    phone: text("phone"),
    nationality: text("nationality"),
    countryOfResidence: text("country_of_residence"),
    status: clientStatus("status").notNull().default("active"),
    primaryConsultantId: uuid("primary_consultant_id").references(() => users.id, { onDelete: "set null" }),
    sourceLeadId: uuid("source_lead_id").references(() => leads.id),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("clients_firm_ref_uq").on(t.firmId, t.ref),
    uniqueIndex("clients_source_lead_uq").on(t.sourceLeadId),
    index("clients_firm_email_idx").on(t.firmId, t.email),
    index("clients_firm_consultant_idx").on(t.firmId, t.primaryConsultantId),
  ],
);

export const consentRecords = pgTable(
  "consent_records",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    leadId: uuid("lead_id").references(() => leads.id),
    clientId: uuid("client_id").references(() => clients.id),
    purpose: consentPurpose("purpose").notNull(),
    granted: boolean("granted").notNull(),
    method: text("method").notNull(), // e.g. "web form checkbox", "verbal on call", "email"
    evidence: text("evidence"),
    recordedById: uuid("recorded_by_id").references(() => users.id, { onDelete: "set null" }),
    recordedAt: timestamp("recorded_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("consent_lead_idx").on(t.leadId), index("consent_client_idx").on(t.clientId)],
);

export const activities = pgTable(
  "activities",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    leadId: uuid("lead_id").references(() => leads.id),
    clientId: uuid("client_id").references(() => clients.id),
    type: activityType("type").notNull(),
    body: text("body"),
    data: jsonb("data").$type<Record<string, unknown>>().notNull().default({}),
    actorId: uuid("actor_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [index("activities_lead_idx").on(t.leadId, t.createdAt), index("activities_client_idx").on(t.clientId, t.createdAt)],
);

export const savedViews = pgTable(
  "saved_views",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    entity: text("entity").notNull().default("leads"),
    query: text("query").notNull(), // URL search string of the view's filters
    isShared: boolean("is_shared").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("saved_views_firm_user_idx").on(t.firmId, t.userId)],
);

/* ───────────────────── Services & pricing (configuration) ───────────────────── */

export type ServiceLine = { label: string; amountMinor: number; kind: "professional" | "government" | "third_party" };
export type ServiceAddOn = { label: string; amountMinor: number | null; note?: string };

export const services = pgTable(
  "services",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    code: text("code").notNull(),
    name: text("name").notNull(),
    jurisdiction: text("jurisdiction").notNull(),
    category: text("category").notNull(),
    currency: text("currency").notNull(),
    totalMinor: integer("total_minor").notNull(),
    depositMinor: integer("deposit_minor").notNull(),
    lines: jsonb("lines").$type<ServiceLine[]>().notNull().default([]),
    addOns: jsonb("add_ons").$type<ServiceAddOn[]>().notNull().default([]),
    isActive: boolean("is_active").notNull().default(true),
    sourceNote: text("source_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("services_firm_code_uq").on(t.firmId, t.code)],
);

/** Every price a service has had. Proposals record the version they quoted. */
export const servicePriceVersions = pgTable(
  "service_price_versions",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id, { onDelete: "cascade" }),
    serviceId: uuid("service_id").notNull(),
    version: integer("version").notNull(),
    name: text("name").notNull(),
    currency: text("currency").notNull(),
    totalMinor: integer("total_minor").notNull(),
    depositMinor: integer("deposit_minor").notNull(),
    lines: jsonb("lines").$type<ServiceLine[]>().notNull().default([]),
    addOns: jsonb("add_ons").$type<ServiceAddOn[]>().notNull().default([]),
    isActive: boolean("is_active").notNull(),
    reason: text("reason"),
    changedById: uuid("changed_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("service_price_versions_uq").on(t.serviceId, t.version), index("service_price_versions_firm_idx").on(t.firmId)],
);

/* ───────────────────────── Proposals ───────────────────────── */

export type ProposalSection = { key: string; title: string; body: string };

export const proposals = pgTable(
  "proposals",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    ref: text("ref").notNull(),
    leadId: uuid("lead_id").notNull(),
    title: text("title").notNull(),
    status: proposalStatus("status").notNull().default("draft"),
    version: integer("version").notNull().default(1),
    recipientName: text("recipient_name").notNull(),
    recipientEmail: citext("recipient_email"),
    currency: text("currency").notNull().default("ZAR"),
    totalMinor: integer("total_minor").notNull().default(0),
    depositMinor: integer("deposit_minor").notNull().default(0),
    sections: jsonb("sections").$type<ProposalSection[]>().notNull().default([]),
    validDays: integer("valid_days").notNull().default(14),
    reviewNote: text("review_note"),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    updatedById: uuid("updated_by_id").references(() => users.id, { onDelete: "set null" }),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    approvedById: uuid("approved_by_id").references(() => users.id, { onDelete: "set null" }),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    releasedById: uuid("released_by_id").references(() => users.id, { onDelete: "set null" }),
    releasedAt: timestamp("released_at", { withTimezone: true }),
    linkTokenHash: text("link_token_hash"),
    linkExpiresAt: timestamp("link_expires_at", { withTimezone: true }),
    firstViewedAt: timestamp("first_viewed_at", { withTimezone: true }),
    respondedAt: timestamp("responded_at", { withTimezone: true }),
    responseName: text("response_name"),
    responseIp: text("response_ip"),
    responseNote: text("response_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("proposals_firm_ref_uq").on(t.firmId, t.ref),
    uniqueIndex("proposals_link_token_uq").on(t.linkTokenHash),
    index("proposals_firm_lead_idx").on(t.firmId, t.leadId),
    index("proposals_firm_status_idx").on(t.firmId, t.status, t.updatedAt),
  ],
);

export const proposalItems = pgTable(
  "proposal_items",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    proposalId: uuid("proposal_id").notNull(),
    position: integer("position").notNull(),
    serviceId: uuid("service_id"),
    servicePriceVersion: integer("service_price_version"),
    label: text("label").notNull(),
    description: text("description"),
    quantity: integer("quantity").notNull().default(1),
    unitMinor: integer("unit_minor").notNull(),
    depositMinor: integer("deposit_minor").notNull().default(0),
    lines: jsonb("lines").$type<ServiceLine[]>().notNull().default([]),
    createdAt: createdAt(),
  },
  (t) => [index("proposal_items_proposal_idx").on(t.proposalId, t.position)],
);

/** Immutable record of what was sent: the client link always shows the released snapshot. */
export type ProposalSnapshot = {
  ref: string;
  title: string;
  version: number;
  firm: { tradingName: string; legalName: string; brandColor: string; slug: string; contactEmail: string | null; contactPhone: string | null; website: string | null };
  recipientName: string;
  recipientEmail: string | null;
  currency: string;
  totalMinor: number;
  depositMinor: number;
  sections: ProposalSection[];
  items: { label: string; description: string | null; quantity: number; unitMinor: number; depositMinor: number; lines: ServiceLine[] }[];
  preparedBy: string | null;
  releasedAt: string;
  validUntil: string;
};

export const proposalVersions = pgTable(
  "proposal_versions",
  {
    id: id(),
    firmId: uuid("firm_id").notNull().references(() => firms.id),
    proposalId: uuid("proposal_id").notNull(),
    version: integer("version").notNull(),
    snapshot: jsonb("snapshot").$type<ProposalSnapshot>().notNull(),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("proposal_versions_uq").on(t.proposalId, t.version)],
);

/* ───────────────────────── Hub intake ───────────────────────── */

export type RoutingMatch = {
  keywordsAny?: string[];
  currentCountryIn?: string[];
  destinationIn?: string[];
};

export const routingRules = pgTable("routing_rules", {
  id: id(),
  orgId: uuid("org_id").notNull().references(() => organisations.id),
  name: text("name").notNull(),
  position: integer("position").notNull(),
  isActive: boolean("is_active").notNull().default(true),
  match: jsonb("match").$type<RoutingMatch>().notNull().default({}),
  action: routingAction("action").notNull().default("route"),
  targetFirmId: uuid("target_firm_id").references(() => firms.id),
  flag: text("flag"), // e.g. "legal_matter", "asylum", "regulated_au"
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const intakeItems = pgTable(
  "intake_items",
  {
    id: id(),
    orgId: uuid("org_id").notNull().references(() => organisations.id),
    status: intakeStatus("status").notNull().default("new"),
    firstName: text("first_name").notNull(),
    lastName: text("last_name"),
    email: citext("email"),
    phone: text("phone"),
    nationality: text("nationality"),
    currentCountry: text("current_country"),
    destinationCountry: text("destination_country"),
    immigrationCategory: text("immigration_category"),
    enquiry: text("enquiry"),
    source: leadSource("source").notNull(),
    sourceRef: text("source_ref"),
    consentContact: boolean("consent_contact").notNull().default(false),
    suggestedFirmId: uuid("suggested_firm_id").references(() => firms.id),
    suggestedRuleId: uuid("suggested_rule_id").references(() => routingRules.id, { onDelete: "set null" }),
    suggestionReason: text("suggestion_reason"),
    flags: text("flags").array().notNull().default(sql`'{}'::text[]`),
    routedFirmId: uuid("routed_firm_id").references(() => firms.id),
    routedLeadId: uuid("routed_lead_id"),
    routedById: uuid("routed_by_id").references(() => users.id, { onDelete: "set null" }),
    routedAt: timestamp("routed_at", { withTimezone: true }),
    note: text("note"),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("intake_status_idx").on(t.status, t.receivedAt),
    uniqueIndex("intake_source_ref_uq").on(t.source, t.sourceRef),
  ],
);

/* ───────────────────────── Audit & outbox ───────────────────────── */

export const auditEvents = pgTable(
  "audit_events",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    orgId: uuid("org_id").notNull(),
    firmId: uuid("firm_id"),
    actorId: uuid("actor_id"),
    action: text("action").notNull(),
    entityType: text("entity_type"),
    entityId: text("entity_id"),
    summary: text("summary"),
    data: jsonb("data").$type<Record<string, unknown>>().notNull().default({}),
    ip: text("ip"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_org_created_idx").on(t.orgId, t.createdAt), index("audit_firm_created_idx").on(t.firmId, t.createdAt)],
);

export const emailOutbox = pgTable("email_outbox", {
  id: id(),
  orgId: uuid("org_id").notNull(),
  firmId: uuid("firm_id"),
  toAddress: text("to_address").notNull(),
  subject: text("subject").notNull(),
  template: text("template").notNull(),
  status: emailStatus("status").notNull(),
  providerMessageId: text("provider_message_id"),
  error: text("error"),
  createdAt: createdAt(),
});
